'use strict';
window.AtlasScience=(()=>{
 const q=s=>document.querySelector(s), all=s=>[...document.querySelectorAll(s)];
 const safe=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const clean=s=>String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
 let data=null,history=[],searchText='',level='explorar';
 const areas={espacio:'Espacio',tierra:'Tierra'};
 const art={espacio:'saturn',tierra:'earth'};
 const href=t=>`#ciencia/${t.id}`;
 const card=t=>`<a class="science-card" href="${href(t)}"><span class="science-label">${safe(t.tag)}</span><h3>${safe(t.title)}</h3><p>${safe(t.summary)}</p><span class="science-card-meta">${t.minutes} min de lectura · 2 preguntas</span></a>`;
 function area(name){
  const list=data.topics.filter(t=>t.area===name),host=q('#'+name);
  host.innerHTML=`<header class="domain-heading domain-${name}"><div><p class="eyebrow">ATLAS / ${areas[name].toUpperCase()}</p><h1>${name==='espacio'?'Del Sol a los límites de lo conocido.':'Un planeta lleno de conexiones.'}</h1><p>${name==='espacio'?'Empieza cerca y viaja más lejos: planetas, estrellas, galaxias y las preguntas que aún investigamos.':'Explora cómo se relacionan las montañas, los océanos, el agua y el clima.'}</p><a class="atlas-button" href="#ciencia/${name==='espacio'?'sistema-solar':'tierra'}">Empieza aquí</a></div><img src="assets/${art[name]}.webp" alt="${name==='espacio'?'Saturno fotografiado por Cassini':'La Tierra fotografiada por Apollo 17'}"></header><p class="image-credit">${name==='espacio'?'Saturno: NASA/JPL/Space Science Institute. Composición en color natural.':'Tierra: NASA, Apollo 17, 1972.'} <a href="#creditos">Créditos de imágenes</a></p><div class="science-section-title"><h2>Elige tu siguiente pregunta</h2><span>${list.length} temas</span></div><div class="science-grid">${list.map(card).join('')}</div><div class="lab-invite"><div><span class="science-label">EXPLORA CON DATOS</span><h2>${name==='espacio'?'Compara mundos y distancias':'¿Qué cambia al descender en el océano?'}</h2></div><a class="atlas-button" href="#laboratorio/${name==='espacio'?'planetas':'oceano'}">Abrir laboratorio</a><a class="atlas-outline" href="#retos/${name}">Resolver un reto</a></div>`;
 }
 function lesson(id){
  const t=data.topics.find(t=>t.id===id),host=q('#ciencia');
  if(!t){host.innerHTML='<h1>Tema no encontrado</h1><a href="#espacio">Explorar Espacio</a>';return;}
  const siblings=data.topics.filter(x=>x.area===t.area),index=siblings.indexOf(t),next=siblings[index+1];
  document.title=t.title+' · Atlas';all('.side-link').forEach(a=>{const active=a.getAttribute('href')==='#'+t.area;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
  host.innerHTML=`<div class="science-breadcrumb"><a href="#${t.area}">${areas[t.area]}</a><span>/ ${safe(t.tag)}</span></div><header class="lesson-heading"><p class="eyebrow">${safe(t.tag)} · ${t.minutes} MINUTOS</p><h1>${safe(t.title)}</h1><p class="science-intro">${safe(t.summary)}</p><div class="lesson-tools"><div role="group" aria-label="Profundidad de lectura"><button data-level="explorar" aria-pressed="${level==='explorar'}">Explorar</button><button data-level="profundizar" aria-pressed="${level==='profundizar'}">Profundizar</button></div><button class="atlas-outline" id="printScience">Imprimir ficha</button></div></header><div class="lesson-layout"><article class="science-reading"><h2>Comprende la idea</h2>${t.reading.map(p=>`<p>${safe(p)}</p>`).join('')}<section id="scienceDeep" ${level==='profundizar'?'':'hidden'}><h2>Un paso más</h2><p>${safe(t.deep)}</p></section><div class="investigate"><p class="science-label">PRUÉBALO Y EXPLICA</p><h2>Tu pequeña investigación</h2><p>${safe(t.activity)}</p></div><details class="teacher-notes"><summary>Para acompañar el aprendizaje</summary><p>Primaria: explica la idea con un dibujo y tus propias palabras. Secundaria: compara la explicación con la fuente, identifica una evidencia y escribe una pregunta pendiente.</p><p>Si enseñas: pide una predicción antes de leer y una explicación después. Usa el reto como conversación, además de revisar los aciertos.</p></details><section class="science-source"><h2>¿De dónde viene la información?</h2><a href="${safe(t.source[1])}" target="_blank" rel="noopener">${safe(t.source[0])}</a>${t.id==='luna-eclipses'?'<p><a href="https://science.nasa.gov/moon/moon-phases/" target="_blank" rel="noopener">NASA · Fases lunares</a></p>':''}<p>Síntesis educativa en español · Revisión: 4 de octubre de 2026. La fuente original puede estar en inglés.</p></section></article><aside class="lesson-check"><span class="science-label">COMPRUEBA LO QUE ENTENDISTE</span><div id="scienceQuiz"></div><a class="text-link" href="#laboratorio/${t.area==='espacio'?'planetas':'oceano'}">Explorar el laboratorio</a></aside></div><nav class="lesson-next" aria-label="Continuar aprendiendo"><a href="#${t.area}">Volver a ${areas[t.area]}</a>${next?`<a class="atlas-button" href="${href(next)}">Siguiente: ${safe(next.title)}</a>`:'<a class="atlas-button" href="#retos/'+t.area+'">Ponte a prueba</a>'}</nav>`;
  all('[data-level]').forEach(b=>b.onclick=()=>{level=b.dataset.level;all('[data-level]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));q('#scienceDeep').hidden=level!=='profundizar';});
  q('#printScience').onclick=()=>window.print();runQuiz(q('#scienceQuiz'),t.quiz);
 }
 function runQuiz(host,questions){
  let at=0,score=0,locked=false,missed=[];
  function draw(){
   locked=false;
   if(at===questions.length){host.innerHTML=`<h3>Reto terminado</h3><p class="quiz-score">${score} / ${questions.length}</p><p>${score===questions.length?'¡Muy bien! Explica una respuesta con tus propias palabras.':'Cada explicación te ayuda a seguir aprendiendo.'}</p>${missed.length?`<details open><summary>Ideas para repasar</summary><ul>${missed.map(x=>`<li>${safe(x)}</li>`).join('')}</ul></details>`:''}<button class="atlas-button" data-restart>Volver a intentar</button>`;host.querySelector('[data-restart]').onclick=()=>{at=0;score=0;missed=[];draw()};return;}
   const [question,options,correct,why]=questions[at];
   host.innerHTML=`<p class="science-label">PREGUNTA ${at+1} DE ${questions.length}</p><progress value="${at}" max="${questions.length}" aria-label="Avance del reto"></progress><h3 tabindex="-1">${safe(question)}</h3><div class="science-answers">${options.map((x,i)=>`<button data-science-answer="${i}">${safe(x)}</button>`).join('')}</div><p class="science-feedback" role="status"></p><button class="atlas-button" data-next disabled>${at===questions.length-1?'Ver resultado':'Siguiente pregunta'}</button>`;
   host.querySelectorAll('[data-science-answer]').forEach(b=>b.onclick=()=>{if(locked)return;locked=true;const ok=Number(b.dataset.scienceAnswer)===correct;if(ok)score++;else missed.push(why);host.querySelectorAll('[data-science-answer]').forEach(x=>{x.disabled=true;if(Number(x.dataset.scienceAnswer)===correct)x.classList.add('answer-right')});host.querySelector('.science-feedback').textContent=(ok?'Correcto. ':'Vamos a revisarlo. ')+why;host.querySelector('[data-next]').disabled=false;});
   host.querySelector('[data-next]').onclick=()=>{if(!locked)return;at++;draw();host.querySelector('h3')?.focus();};
  }draw();
 }
 function challenges(name){
  const selected=areas[name]?name:'espacio',host=q('#retos');
  host.innerHTML=`<p class="eyebrow">APRENDER A TU RITMO</p><h1>Un reto, ocho preguntas.</h1><p>Elige un área. Recibirás una explicación después de cada respuesta.</p><label class="science-select">Área<select id="scienceChallengeArea"><option value="espacio" ${selected==='espacio'?'selected':''}>Espacio</option><option value="tierra" ${selected==='tierra'?'selected':''}>Tierra</option></select></label><button class="atlas-button" id="newScienceRound">Nueva ronda</button><div id="scienceArena" class="science-arena"></div><p><a href="#juegos">Abrir los retos de Historia por equipos</a></p>`;
  function start(){const deck=data.topics.filter(t=>t.area===q('#scienceChallengeArea').value).flatMap(t=>t.quiz).slice();for(let i=deck.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[deck[i],deck[j]]=[deck[j],deck[i]];}runQuiz(q('#scienceArena'),deck.slice(0,8));}
  q('#newScienceRound').onclick=start;q('#scienceChallengeArea').onchange=start;start();
 }
 function laboratory(which){
  const ocean=which==='oceano',host=q('#laboratorio');
  host.innerHTML=`<p class="eyebrow">LABORATORIO ATLAS</p><h1>Haz una pregunta. Cambia una variable.</h1><nav class="lab-tabs" aria-label="Laboratorios"><a href="#laboratorio/planetas" ${!ocean?'aria-current="page"':''}>Planetas y distancias</a><a href="#laboratorio/oceano" ${ocean?'aria-current="page"':''}>Luz en el océano</a></nav><div id="labBody"></div>`;
  if(ocean){q('#labBody').innerHTML=`<div class="ocean-lab"><div><span class="science-label">MODELO DE ZONAS DE LUZ</span><h2>Descubre qué cambia al descender</h2><label for="oceanDepth">Profundidad: <output id="depthValue">0 m</output></label><input id="oceanDepth" type="range" min="0" max="6000" step="50" value="0"><div class="depth-presets"><button data-depth="0">Superficie</button><button data-depth="500">500 m</button><button data-depth="2000">2 000 m</button><button data-depth="6000">6 000 m</button></div><p>Las zonas son aproximadas: la claridad del agua modifica la penetración de luz. Este modelo clasifica la luz solar, no todos los ecosistemas.</p><a href="#ciencia/profundidades">Leer sobre las profundidades</a></div><div class="depth-display" id="depthDisplay" role="status"><span id="depthNumber"></span><h2 id="depthZone"></h2><p id="depthExplanation"></p><div class="depth-meter" aria-hidden="true"><span id="depthMarker"></span></div><small>Escala de profundidad: 0–6 000 m</small></div></div><p class="science-source">Fuente: <a href="https://oceanservice.noaa.gov/facts/light_travel.html" target="_blank" rel="noopener">NOAA · Luz en el océano</a></p>`;
   function update(){const d=Number(q('#oceanDepth').value);q('#depthValue').textContent=d.toLocaleString('es-MX')+' m';q('#depthNumber').textContent=d.toLocaleString('es-MX')+' metros';q('#depthZone').textContent=d<200?'Zona iluminada':d<1000?'Zona de penumbra':'Sin luz solar';q('#depthExplanation').textContent=d<200?'Aquí se concentra la luz que permite la fotosíntesis.':d<1000?'La luz solar disminuye mucho. La fotosíntesis resulta insuficiente en la mayor parte de esta zona.':'No llega luz solar útil. Algunos organismos producen su propia luz; la vida sigue siendo posible.';q('#depthDisplay').dataset.zone=d<200?'light':d<1000?'twilight':'dark';q('#depthMarker').style.width=(d/6000*100)+'%';}
   q('#oceanDepth').oninput=update;all('[data-depth]').forEach(b=>b.onclick=()=>{q('#oceanDepth').value=b.dataset.depth;update()});update();return;
  }
  const options=selected=>data.planets.map(p=>`<option value="${p.id}" ${selected===p.id?'selected':''}>${p.name}</option>`).join('');
  q('#labBody').innerHTML=`<div class="planet-controls"><label>Primer planeta<select id="planetA">${options('tierra')}</select></label><label>Segundo planeta<select id="planetB">${options('jupiter')}</select></label></div><div id="planetComparison" aria-live="polite"></div><div class="scale-lab"><div><span class="science-label">EL SISTEMA SOLAR EN TU PATIO</span><h2>Si la Tierra estuviera a…</h2><label for="solarScale"><output id="scaleValue">1</output> metro(s) del Sol</label><input id="solarScale" type="range" min="0.1" max="3" step="0.1" value="1"><p>Las barras usan una escala lineal de distancia media. No representan tamaños, posiciones actuales ni distancias desde la Tierra.</p></div><div id="solarRuler"></div></div><p class="science-source">Diámetros ecuatoriales y distancias medias aproximadas. 1 UA ≈ 149,6 millones de km. Fuentes: <a href="https://science.nasa.gov/solar-system/planet-sizes-and-locations-in-our-solar-system/" target="_blank" rel="noopener">NASA · Planetas</a>, <a href="https://nssdc.gsfc.nasa.gov/planetary/factsheet/" target="_blank" rel="noopener">Ficha planetaria</a> y <a href="https://science.nasa.gov/mission/voyager/fact-sheet/" target="_blank" rel="noopener">Voyager</a>.</p>`;
  function compare(){const a=data.planets.find(p=>p.id===q('#planetA').value),b=data.planets.find(p=>p.id===q('#planetB').value);q('#planetComparison').innerHTML=`<div class="comparison-grid">${[a,b].map(p=>`<article><span class="science-label">${p.kind}</span><h2>${p.name}</h2><p>${p.note}</p><dl><dt>Diámetro ecuatorial</dt><dd>${p.diameter.toLocaleString('es-MX')} km</dd><dt>Distancia media al Sol</dt><dd>${p.au.toLocaleString('es-MX')} UA</dd></dl></article>`).join('')}</div><p class="comparison-result">${a.id===b.id?'Elegiste el mismo planeta. Selecciona otro para descubrir diferencias.':`${b.name} tiene aproximadamente ${(b.diameter/a.diameter).toLocaleString('es-MX',{maximumFractionDigits:2})} veces el diámetro de ${a.name}. Su distancia media al Sol es ${(b.au/a.au).toLocaleString('es-MX',{maximumFractionDigits:2})} veces la de ${a.name}.`}</p>`;}
  function ruler(){const scale=Number(q('#solarScale').value);q('#scaleValue').textContent=scale.toLocaleString('es-MX');q('#solarRuler').innerHTML=data.planets.map(p=>`<div class="ruler-row"><span>${p.name}</span><div class="ruler-track"><span style="width:${p.au/30.069*100}%"></span></div><strong>${(p.au*scale).toLocaleString('es-MX',{maximumFractionDigits:2})} m</strong></div>`).join('');}
  q('#planetA').onchange=compare;q('#planetB').onchange=compare;q('#solarScale').oninput=ruler;compare();ruler();
 }
 function search(text){searchText=text;location.hash='buscar';results();}
 function results(){if(!data)return;const term=clean(searchText.trim()).replace(/\b(\w{4,})s\b/g,'$1');const found=data.topics.filter(t=>clean([t.title,t.summary,t.tag,...t.reading,t.deep].join(' ')).includes(term));const past=history.filter(t=>clean([t.title,t.summary,t.era].join(' ')).includes(term));q('#buscar').innerHTML=`<p class="eyebrow">ESPACIO · TIERRA · HISTORIA</p><h1>Encuentra tu próxima exploración</h1><form class="atlas-search" id="resultForm"><label class="sr-only" for="resultTerm">Buscar en Atlas</label><input id="resultTerm" type="search" value="${safe(searchText)}" placeholder="Planetas, océanos, Revolución…"><button class="atlas-button">Buscar</button></form><p role="status">${found.length+past.length} resultados${term?' para “'+safe(searchText)+'”':''}</p><div class="science-grid">${found.map(card).join('')}${past.map(t=>`<a class="science-card" href="#ruta/${t.id}"><span class="science-label">HISTORIA</span><h3>${safe(t.title)}</h3><p>${safe(t.summary)}</p><span>Ruta histórica · PDF</span></a>`).join('')}</div>${found.length+past.length===0?'<p>Prueba con una palabra más general, como “agua”, “Sol” o “México”.</p>':''}`;q('#resultForm').onsubmit=e=>{e.preventDefault();searchText=q('#resultTerm').value;results();};}
 function route(hash){if(!data)return;const [section,id]=hash.split('/');if(section==='ciencia')lesson(id);if(section==='laboratorio')laboratory(id);if(section==='retos')challenges(id);if(section==='buscar')results();}
 async function init(past){history=past;try{const r=await fetch('data/science.json');if(!r.ok)throw Error('data');data=await r.json();area('espacio');area('tierra');route(location.hash.slice(1));q('#searchBtn').onclick=()=>search(q('#searchInput').value);q('#searchInput').onkeydown=e=>{if(e.key==='Enter')search(q('#searchInput').value);};}catch(e){for(const id of ['espacio','tierra','ciencia','laboratorio','retos'])q('#'+id).innerHTML='<h1>No se pudo cargar esta exploración</h1><p>Comprueba tu conexión y vuelve a intentarlo.</p><button class="atlas-button" data-retry-science>Reintentar</button>';all('[data-retry-science]').forEach(b=>b.onclick=()=>init(past));}}
 return {init,route,search};
})();
